for(const kind of ['verifyFencerAuthority','verifyCheckpointEvidence','verifyGuardEvidence','verifyOutcomeEvidence','verifyRecoveryAuthority','verifyClock','verifyCustodyEvidence'])test('throwing verifier never exposes private transport text '+kind,async()=>{const z=fixture(),i=z.input();if(kind==='verifyOutcomeEvidence'||kind==='verifyRecoveryAuthority')await z.adapter().execute(i);z.config[kind]=()=>{throw Error('private credential value');};await denied(()=>kind==='verifyOutcomeEvidence'||kind==='verifyRecoveryAuthority'?z.adapter().reconcile(z.recovery(i.command)):z.adapter().execute(i));});
test('driver callback result marker alone cannot bypass false durable outcome',async()=>{const z=fixture(),i=z.input();z.fault.callbackOnly=true;await denied(()=>z.adapter().execute(i));assert.equal(z.entries.length,0);assert.equal(z.custodyEntries.length,0);});
test('registry-history audit metadata injection cannot survive mixed-prefix validation',async()=>{const pair=writerPair(),{z,w,i}=pair;await w.repo().execute(i);publishConsumption(pair);z.entries[0].record.audit.customer='forbidden';await denied(()=>z.adapter().execute(emergency(z,pair.original)));});
test('original provider proof data is immutable before asynchronous boundaries',async()=>{const z=fixture(),i=z.input(),cmd=clone(i.command),promise=z.adapter().execute(i);i.command.key.tenant.storeId='d'.repeat(24);i.command.reasonCode='ALTERED';const r=await promise;assert.deepEqual(r.key,cmd.key);assert.equal(z.entries[0].record.event.command.reasonCode,cmd.reasonCode);});
for(const field of ['prefixDigest','anchorDigest'])test('fresh normal PREPARE point cannot substitute another '+field,async()=>{const z=fixture(),i=z.input();i.command.preparePoint[field]='f'.repeat(64);i.fencerProof=z.auth(i.command);await denied(()=>z.adapter().execute(i));assert.equal(z.entries.length,0);});
test('constructor rejects accessor methods without invoking them',()=>{const z=fixture();let called=0;Object.defineProperty(z.config.client,'startSession',{get(){called++;return ()=>{};}});assert.throws(()=>z.adapter());assert.equal(called,0);});
test('multiple original source proofs are verified through separate roots during reconciliation',async()=>{const z=fixture(),i=z.input();await z.adapter().execute(i);z.calls=[];await z.adapter().reconcile(z.recovery(i.command));for(const name of ['recovery','clock','outcome','checkpoint','guard','custody'])assert.ok(z.calls.includes('verify.'+name));assert.equal(z.calls.includes('verify.fencer'),false);assert.equal(z.calls.includes('guard.write'),false);});
test('actual consumer contract rejects the actual advancer result under independent proof roots',async()=>{const z=fixture(),r=await z.adapter().execute(z.input());const roots=new WeakMap();const verify=p=>{if(!roots.has(p))throw Error('not consumer provenance');return roots.get(p);};const consumer=createTrustedObservationContract({authorityId:z.key.authorityId,sourceId:'consumer_root',audience:'consumer',authorityEpoch:z.key.authorityEpoch,verifyCheckpoint:verify,verifySource:verify,verifyClock:verify,verifyBootstrap:verify});assert.throws(()=>consumer.evaluate({context:{authorityId:z.key.authorityId,tenant:z.key.tenant,sequence:1,stateDigest:'a'.repeat(64),now:z.now,genesis:false},checkpointProof:r,sourceProof:{},clockProof:{}}));});
test('original durable commit inside grant but beyond bounded transaction window denies recovery',async()=>{const z=fixture(),i=z.input();z.fault.lostCommit=true;await denied(()=>z.adapter().execute(i));const op=z.outcomes.get(i.command.barrierOperationId);op.commitEvidence.committedAt++;z.entries[0].commitEvidence=clone(op.commitEvidence);z.now+=61;await denied(()=>z.adapter().reconcile(z.recovery(i.command)));assert.equal(z.custodyEntries.length,0);});
